# extract 4-connected components of non-bg source, ignoring row1 marker isolated 0s as pieces
seen=set(); pieces=[]
for r,row in enumerate(top):
 for c,v in enumerate(row):
  if v!=1 and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c)); comp=[]
   while st:
    rr,cc=st.pop();comp.append((rr,cc,top[rr][cc]))
    for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,nc:=cc-1),(rr,nc+2)):
     if 0<=nr<len(top) and 0<=nc<len(top[0]) and top[nr][nc]!=1 and (nr,nc) not in seen:
      seen.add((nr,nc));st.append((nr,nc))
   pieces.append(comp)
[(len(p), sorted(set(v for r,c,v in p)), (max(r for r,c,v in p)-min(r for r,c,v in p)+1,max(c for r,c,v in p)-min(c for r,c,v in p)+1), sorted((r-min(x[0] for x in p),c-min(x[1] for x in p),v) for r,c,v in p)) for p in pieces]

# reshape normalized source comps; mask global output coordinate use rows 1..6 in bottom
from collections import defaultdict
mask={(r,c) for r in range(1,7) for c in range(20) if bottom[r][c]==1}
non_single=[p for p in pieces if len(p)>1]
shapes=[]
for p in non_single:
 mr=min(r for r,c,v in p); mc=min(c for r,c,v in p)
 shapes.append([(r-mr,c-mc,v) for r,c,v in p])
# placements by piece id
cands=[]
for sh in shapes:
 h=max(r for r,c,v in sh)+1; w=max(c for r,c,v in sh)+1
 pc=[]
 for r in range(1,7-h+1):
  for c in range(0,20-w+1):
   cells={(r+dr,c+dc) for dr,dc,v in sh}
   if cells<=mask: pc.append((r,c,cells))
 cands.append(pc)
[len(x) for x in cands],len(mask),sum(len(p) for p in non_single)
